import React, { useEffect } from 'react';
import './Login.css';

const Login = () => {
  // Verificar si venimos de un redirect exitoso o con error
  useEffect(() => {
    const urlParams = new URLSearchParams(window.location.search);
    const loginStatus = urlParams.get('login');
    const error = urlParams.get('error');

    if (loginStatus === 'success') {
      console.log('Login exitoso! Redirigiendo al dashboard...');
      // Limpiar URL
      window.history.replaceState({}, document.title, window.location.pathname);
      // Aquí puedes redirigir al dashboard o página principal
      // window.location.href = '/dashboard';
    }

    if (error) {
      console.error('Error en autenticación:', error);
      alert('Error en la autenticación: ' + error);
      window.history.replaceState({}, document.title, window.location.pathname);
    }
  }, []);

  const handleGubUyLogin = () => {
    // Generar state único para seguridad CSRF
    const state = Math.random().toString(36).substring(2, 15) + Math.random().toString(36).substring(2, 15);

    // Guardar state en sessionStorage para validarlo después
    sessionStorage.setItem('oauth_state', state);

    // Construir URL de autorización directamente
    const authUrl = new URL('https://auth-testing.iduruguay.gub.uy/oidc/v1/authorize');
    authUrl.searchParams.set('response_type', 'code');
    authUrl.searchParams.set('client_id', '890192');
    authUrl.searchParams.set('redirect_uri', 'http://localhost:8080/hcen-web/api/auth/callback');
    authUrl.searchParams.set('scope', 'openid document personal_info auth_info');
    authUrl.searchParams.set('state', state);

    // Redirigir directamente a ID Uruguay
    window.location.href = authUrl.toString();
  };

  return (
    <div className="login-container">
      <div className="login-content">
        {/* Logo Section */}
        <div className="logo-section">
          <div className="logo">
            <div className="logo-icon">
              <svg width="40" height="40" viewBox="0 0 40 40" fill="none">
                <path 
                  d="M20 4L24 12H32L26 18L28 26L20 22L12 26L14 18L8 12H16L20 4Z" 
                  fill="var(--indigo-dye)"
                />
              </svg>
            </div>
            <span className="logo-text">HCEN</span>
          </div>
        </div>

        {/* Login Form Card */}
        <div className="login-card">
          <h1 className="login-title">Iniciar Sesión en HCEN</h1>

          <div className="login-form">
            <button onClick={handleGubUyLogin} className="login-button gubuy-button">
              Iniciar Sesión con gub.uy
            </button>
          </div>
        </div>

        {/* Footer */}
        <div className="footer">
          <div className="footer-separator"></div>
          <p className="copyright">© 2024 HCEN. Todos los derechos reservados.</p>
        </div>
      </div>
    </div>
  );
};

export default Login;
